insert into public.career_roles (id, title, summary, position) values
  ('data-analyst', 'Data Analyst', 'Turns raw data into answers: cleans data, queries databases and builds charts and dashboards that teams use to decide.', 1),
  ('senior-data-analyst', 'Senior Data Analyst', 'Owns analyses end to end: designs experiments, models outcomes and explains trade-offs to decision makers.', 2),
  ('data-scientist', 'Data Scientist', 'Builds statistical and machine learning models to predict, forecast and explain, and checks that they hold up.', 3),
  ('analytics-manager', 'Analytics Manager', 'Leads a data team: sets priorities, runs the experimentation programme and owns data governance.', 4),
  ('ml-ai-specialist', 'ML / AI Specialist', 'Applies machine learning to business problems: frames the task, trains and evaluates models and explains results.', 5),
  ('ml-engineer', 'ML Engineer', 'Builds machine learning systems that run in production: training pipelines, serving, monitoring and retraining.', 6),
  ('ai-engineer', 'AI Engineer', 'Builds products on large language models: retrieval, tools and agents, with evaluations that catch failures.', 7),
  ('ai-product-lead', 'AI Product / ML Lead', 'Decides what AI to build and how to measure it: evaluation, governance, experimentation and stakeholder alignment.', 8),
  ('mlops-engineer', 'MLOps Engineer', 'Owns the platform models run on: orchestration, deployment, monitoring and infrastructure as code.', 9);
